using System;using System.Reflection;using Por.Core;
public static class SourceApiChecks {public static void Run(){int n=0,fail=0;
 n++;if(!Check(typeof(ClassCal),"RecalcBaseSkills",typeof(void),new Type[]{typeof(Types.TCharRecord)}))fail++;
 n++;if(!Check(typeof(ClassCal),"AwardWisdomBonus",typeof(void),new Type[]{typeof(Types.TCharRecord)}))fail++;
 n++;if(!Check(typeof(ClassCal),"RecalcSaves",typeof(void),new Type[]{typeof(Types.TCharRecord)}))fail++;
 n++;if(!Check(typeof(ClassCal),"RecalcThiefSkills",typeof(void),new Type[]{typeof(Types.TCharRecord)}))fail++;
 n++;if(!Check(typeof(ClassCal),"RaceAbilityMin",typeof(byte),new Type[]{typeof(sbyte),typeof(sbyte),typeof(sbyte)}))fail++;
 n++;if(!Check(typeof(ClassCal),"RaceAbilityMax",typeof(byte),new Type[]{typeof(sbyte),typeof(sbyte),typeof(sbyte)}))fail++;
 n++;if(!Check(typeof(ClassCal),"ConHpPerDie",typeof(sbyte),new Type[]{typeof(sbyte),typeof(byte)}))fail++;
 n++;if(!Check(typeof(ClassCal),"ConHpBonus",typeof(sbyte),new Type[]{typeof(Types.TCharRecord),typeof(byte)}))fail++;
 n++;if(!Check(typeof(ClassCal),"DivideAmongClasses",typeof(byte),new Type[]{typeof(byte),typeof(sbyte),typeof(byte)}))fail++;
 n++;if(!Check(typeof(ClassCal),"HpMinimum",typeof(byte),new Type[]{typeof(Types.TCharRecord)}))fail++;
 n++;if(!Check(typeof(ClassCal),"HpMaximum",typeof(byte),new Type[]{typeof(Types.TCharRecord)}))fail++;
 n++;if(!Check(typeof(ClassCal),"RollFirstLevelHp",typeof(byte),new Type[]{typeof(Types.TCharRecord),typeof(byte)}))fail++;
 n++;if(!Check(typeof(ClassCal),"HitDieFloor",typeof(byte),new Type[]{typeof(byte)}))fail++;
 n++;if(!Check(typeof(ClassCal),"ConHpTotal",typeof(short),new Type[]{typeof(Types.TCharRecord),typeof(byte)}))fail++;
 n++;if(!Check(typeof(ClassCal),"ExperienceShare",typeof(int),new Type[]{typeof(Types.TCharRecord),typeof(int)}))fail++;
 n++;if(!Check(typeof(Dice),"RollDice",typeof(byte),new Type[]{typeof(byte),typeof(byte)}))fail++;
 n++;if(!Check(typeof(Dice),"RollDamageDice",typeof(byte),new Type[]{typeof(byte),typeof(byte)}))fail++;
 n++;if(!Check(typeof(Clock),"ValidateClock",typeof(void),new Type[]{typeof(Types.TClock),typeof(bool)}))fail++;
 n++;if(!Check(typeof(Clock),"SetFromMinutes",typeof(void),new Type[]{typeof(Types.TClock),typeof(ushort)}))fail++;
 n++;if(!Check(typeof(Party),"IsPartyMember",typeof(bool),new Type[]{typeof(Types.TCharRecord)}))fail++;
 n++;if(!Check(typeof(Party),"SelectPrevNextChar",typeof(void),new Type[]{typeof(char)}))fail++;
 n++;if(!Check(typeof(Party),"LastCreature",typeof(Types.TCharRecord),new Type[]{}))fail++;
 n++;if(!Check(typeof(Party),"PrevCreature",typeof(Types.TCharRecord),new Type[]{typeof(Types.TCharRecord)}))fail++;
 n++;if(!Check(typeof(Party),"NextCreature",typeof(Types.TCharRecord),new Type[]{typeof(Types.TCharRecord)}))fail++;
 n++;if(!Check(typeof(MoneyCal),"CopperValue",typeof(int),new Type[]{typeof(Types.TMoney)}))fail++;
 n++;if(!Check(typeof(MoneyCal),"CoinValueInGold",typeof(int),new Type[]{typeof(Types.TMoney)}))fail++;
 n++;if(!Check(typeof(MoneyCal),"CoinsOf",typeof(void),new Type[]{typeof(Types.TCharRecord),typeof(Types.TMoney)}))fail++;
 n++;if(!Check(typeof(MoneyCal),"CreatureCopper",typeof(int),new Type[]{typeof(Types.TCharRecord)}))fail++;
 n++;if(!Check(typeof(MoneyCal),"CreatureGold",typeof(int),new Type[]{typeof(Types.TCharRecord)}))fail++;
 n++;if(!Check(typeof(MoneyCal),"MakeChange",typeof(void),new Type[]{typeof(int),typeof(int),typeof(Types.TMoney)}))fail++;
 n++;if(!Check(typeof(MoneyCal),"WhoPays",typeof(byte),new Type[]{typeof(Types.TCharRecord),typeof(int)}))fail++;
 n++;if(!Check(typeof(MoneyCal),"ItemBundle",typeof(byte),new Type[]{typeof(Types.TItemRec)}))fail++;
 n++;if(!Check(typeof(MoneyCal),"ItemValue",typeof(int),new Type[]{typeof(Types.TItemRec)}))fail++;
 n++;if(!Check(typeof(MoneyCal),"ItemSalePrice",typeof(ushort),new Type[]{typeof(Types.TItemRec)}))fail++;
 n++;if(!Check(typeof(MoneyCal),"ParseMoneyType",typeof(sbyte),new Type[]{typeof(string),typeof(string).MakeByRefType()}))fail++;
 n++;if(!Check(typeof(Stats),"BlockOf",typeof(Stats.TStatBlock),new Type[]{typeof(Types.TCharRecord)}))fail++;
 n++;if(!Check(typeof(Stats),"Count",typeof(void),new Type[]{typeof(Types.TCharRecord),typeof(byte),typeof(int)}))fail++;
 n++;if(!Check(typeof(Stats),"Damaged",typeof(void),new Type[]{typeof(Types.TCharRecord),typeof(Types.TCharRecord),typeof(byte),typeof(bool)}))fail++;
 n++;if(!Check(typeof(Stats),"BledOut",typeof(void),new Type[]{typeof(Types.TCharRecord)}))fail++;
 n++;if(!Check(typeof(Stats),"Healed",typeof(void),new Type[]{typeof(Types.TCharRecord),typeof(Types.TCharRecord),typeof(byte),typeof(bool)}))fail++;
 n++;if(!Check(typeof(Stats),"MarkCoins",typeof(void),new Type[]{}))fail++;
 n++;if(!Check(typeof(Stats),"SettleCoins",typeof(void),new Type[]{}))fail++;
 n++;if(!Check(typeof(Stats),"Forget",typeof(void),new Type[]{typeof(Types.TCharRecord)}))fail++;
 n++;if(!Check(typeof(Stats),"ResetGame",typeof(void),new Type[]{}))fail++;
 n++;if(!Check(typeof(Stats),"WriteChar",typeof(void),new Type[]{typeof(Types.TCharRecord),typeof(string)}))fail++;
 n++;if(!Check(typeof(Stats),"ReadChar",typeof(void),new Type[]{typeof(Types.TCharRecord),typeof(string)}))fail++;
 n++;if(!Check(typeof(Stats),"WriteGame",typeof(void),new Type[]{typeof(string)}))fail++;
 n++;if(!Check(typeof(Stats),"ReadGame",typeof(void),new Type[]{typeof(string)}))fail++;
Console.WriteLine("Source public API signatures="+n+" failed="+fail);if(fail!=0)throw new Exception("Source API widths/signatures mismatched");}
static bool Check(Type unit,string name,Type ret,Type[] args){var m=unit.GetMethod(name,BindingFlags.Public|BindingFlags.Static);if(m==null){Console.WriteLine("API FAIL "+unit.Name+"."+name+" missing");return false;}bool ok=m.ReturnType==ret;var p=m.GetParameters();ok &= p.Length==args.Length;for(int i=0;i<Math.Min(p.Length,args.Length);i++)ok &= p[i].ParameterType==args[i];if(!ok)Console.WriteLine("API FAIL "+unit.Name+"."+name+" expected "+ret+"("+String.Join<Type>(",",args)+") got "+m);return ok;}}
